import re
from datetime import datetime

_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_ANGLE_RE = re.compile(r"<([^>]*)>")
_EXT_RE = re.compile(r"ext|x|#", re.IGNORECASE)   # leftmost marker wins
_OPTED_OUT = {"y", "yes", "true", "1"}
_FIELDS = ("first_name", "last_name", "email", "phone", "zip",
           "tags", "opted_out", "updated", "source")


def _text(row, key):
    v = row.get(key)
    return "" if v is None else str(v)


def _normalize_email(raw):
    m = _ANGLE_RE.search(raw)
    s = (m.group(1) if m else raw).strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.replace(".", "").split("+", 1)[0]
            s = local + "@gmail.com"
    return s


def _is_valid_email(s):
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    return (bool(local) and "." in domain
            and not domain.startswith(".") and not domain.endswith("."))


def _normalize_phone(raw):
    """Returns the 10-digit phone if valid, else ''."""
    m = _EXT_RE.search(raw)
    s = raw[:m.start()] if m else raw
    digits = re.sub(r"[^0-9]", "", s)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return ""


def _normalize_zip(raw):
    s = raw.strip()
    if "-" in s:                      # ZIP+4 -> keep the part before the hyphen
        s = s.split("-", 1)[0].strip()
    if re.fullmatch(r"[0-9]{4}", s):  # Excel ate the leading zero
        s = "0" + s
    return s if re.fullmatch(r"[0-9]{5}", s) else ""


def _normalize_name(raw):
    s = raw.strip()
    if s.isupper() or s.islower():
        return s.title()
    return s


def _parse_updated(raw):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def _split_tags(raw):
    return {t.strip().lower() for t in re.split(r"[;,]", raw) if t.strip()}


def dedupe_contacts(rows):
    # ---- 1. Normalize every row; drop rows with no valid email and no valid phone
    recs = []
    for idx, row in enumerate(rows):
        email = _normalize_email(_text(row, "email"))
        if not _is_valid_email(email):
            email = ""
        phone = _normalize_phone(_text(row, "phone"))
        if not email and not phone:
            continue
        recs.append({
            "idx": idx,
            "first_name": _normalize_name(_text(row, "first_name")),
            "last_name": _normalize_name(_text(row, "last_name")),
            "email": email,
            "phone": phone,
            "zip": _normalize_zip(_text(row, "zip")),
            "tags": _split_tags(_text(row, "tags")),
            "opted_out": _text(row, "opted_out").strip().lower() in _OPTED_OUT,
            "updated": _parse_updated(_text(row, "updated")),
            "source": _text(row, "source").strip().lower(),
        })

    # ---- 2. Group matching rows (union-find gives transitivity)
    parent = list(range(len(recs)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(i, j):
        ri, rj = find(i), find(j)
        if ri != rj:
            parent[max(ri, rj)] = min(ri, rj)

    by_email = {}
    by_phone_last = {}
    for i, r in enumerate(recs):
        if r["email"]:
            if r["email"] in by_email:
                union(i, by_email[r["email"]])
            else:
                by_email[r["email"]] = i
        if r["phone"] and r["last_name"]:
            key = (r["phone"], r["last_name"].lower())
            if key in by_phone_last:
                union(i, by_phone_last[key])
            else:
                by_phone_last[key] = i

    groups = {}  # root -> members; insertion order = order of earliest row
    for i in range(len(recs)):
        groups.setdefault(find(i), []).append(recs[i])

    # ---- 3. Build one output dict per person
    def best(members, field):
        cands = [r for r in members if r[field]]
        if not cands:
            return ""
        # prefer source "manual", then most recent updated, then earliest in input
        return max(cands, key=lambda r: (r["source"] == "manual",
                                         r["updated"],
                                         -r["idx"]))[field]

    out = []
    for members in groups.values():
        tags = set()
        for r in members:
            tags |= r["tags"]
        person = {
            "first_name": best(members, "first_name"),
            "last_name": best(members, "last_name"),
            "email": best(members, "email"),
            "phone": best(members, "phone"),
            "zip": best(members, "zip"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(r["opted_out"] for r in members) else "N",
            "updated": max(r["updated"] for r in members).strftime("%Y-%m-%d"),
            "source": best(members, "source"),
        }
        out.append({k: person[k] for k in _FIELDS})
    return out
```

A few implementation notes so you know what to expect:

- **Phone extension markers:** the regex cuts at the *leftmost* of `x`, `ext`, or `#` (case-insensitive), so `617-555-0100 ext. 12` and `617-555-0100x12` both become `6175550100`.
- **Gmail:** `Ann.Lee+alerts@GoogleMail.com` → `annlee@gmail.com`. Addresses with zero or multiple `@` are left as-is and then fail validation, so they're treated as empty.
- **Phone + last-name matching** uses the normalized (title-cased) last name lowercased, so `SMITH`, `Smith`, and `smith` all match.
- **Output order** of dict keys matches the input field order; people are listed by earliest input row.
- **Bad `updated` values** raise a `ValueError` naming the offending value rather than silently guessing — the spec says that field is never empty, and a wrong date could change which name/email wins a group. If your export does have blanks there, let me know and I'll add a fallback.
- Before sending, I'd filter the result with `[p for p in dedupe_contacts(rows) if p["opted_out"] == "N" and p["email"]]` — the function keeps opted-out people (flagged `"Y"`) so you have a record of them, but they obviously shouldn't get the alert.
